solutions.naive:
class Solution:
    def validUtf8(self, data: list[int]) -> bool:
        bits = [format(x, "08b") for x in data]
        i = 0
        while i < len(bits):
            b = bits[i]
            if b[0] == "0":
                need = 0
            elif b.startswith("110"):
                need = 1
            elif b.startswith("1110"):
                need = 2
            elif b.startswith("11110"):
                need = 3
            else:
                return False
            if i + need >= len(bits):
                return False
            for j in range(i + 1, i + need + 1):
                if not bits[j].startswith("10"):
                    return False
            i += need + 1
        return True

solutions.better:
class Solution:
    def validUtf8(self, data: list[int]) -> bool:
        i = 0
        while i < len(data):
            byte = data[i]
            mask = 128
            leading = 0
            while byte & mask:
                leading += 1
                mask >>= 1
            if leading == 0:
                i += 1
                continue
            if leading == 1 or leading > 4 or i + leading > len(data):
                return False
            for j in range(i + 1, i + leading):
                if (data[j] & 192) != 128:
                    return False
            i += leading
        return True

