class Solution:
    def validUtf8(self, data: list[int]) -> bool:
        remaining = 0
        for byte in data:
            if remaining:
                if (byte >> 6) != 0b10:
                    return False
                remaining -= 1
            else:
                if (byte >> 7) == 0:
                    remaining = 0
                elif (byte >> 5) == 0b110:
                    remaining = 1
                elif (byte >> 4) == 0b1110:
                    remaining = 2
                elif (byte >> 3) == 0b11110:
                    remaining = 3
                else:
                    return False
        return remaining == 0

